export function taskLabel(name: string, completed: boolean): string {
  return (completed ? '[x] ' : '[ ] ') + name;
}

import assert from 'node:assert/strict';
import { test } from 'node:test';
import { taskLabel } from '../src/labels.ts';

test('completed task receives [x] prefix', () => {
  assert.equal(taskLabel('publish release', true), '[x] publish release');
});

test('incomplete task receives [ ] prefix', () => {
  assert.equal(taskLabel('write documentation', false), '[ ] write documentation');
});

test('preserves empty string name exactly', () => {
  assert.equal(taskLabel('', true), '[x] ');
  assert.equal(taskLabel('', false), '[ ] ');
});

test('preserves whitespace and special characters in name exactly', () => {
  assert.equal(taskLabel('  trimmed? no!  ', true), '[x]   trimmed? no!  ');
  assert.equal(taskLabel('task: #123 [wip]', false), '[ ] task: #123 [wip]');
});

