import assert from 'node:assert/strict';
import { test } from 'node:test';
import { makeRouter } from '../src/app.ts';
import { unrelatedHelper, documentation } from '../src/routes/accounts.ts';
import { auditCallback } from '../src/routes/orders.ts';

test('router has all 5 routes in correct order', () => {
  const router = makeRouter();
  assert.equal(router.routes.length, 5);
  assert.deepEqual(
    router.routes.map(r => ({ method: r.method, path: r.path })),
    [
      { method: 'GET', path: '/accounts/:id' },
      { method: 'POST', path: '/accounts' },
      { method: 'GET', path: '/health' },
      { method: 'GET', path: '/orders/:id' },
      { method: 'DELETE', path: '/orders/:id' },
    ]
  );
});

test('successful handling for all routes', async () => {
  const router = makeRouter();
  const mockRes = { send: (val) => val };
  const noopNext = (err) => {
    if (err) throw err;
  };

  // GET /accounts/:id
  const res1 = await router.routes[0].handler({ id: '123' }, mockRes, noopNext);
  assert.equal(res1, 'account:123');

  // POST /accounts
  const res2 = await router.routes[1].handler({ id: '456' }, mockRes, noopNext);
  assert.equal(res2, 'created:456');

  // Synchronous GET /health
  const res3 = router.routes[2].handler({}, mockRes, noopNext);
  assert.equal(res3, 'ok');

  // GET /orders/:id
  const res4 = await router.routes[3].handler({ id: 'abc' }, mockRes, noopNext);
  assert.equal(res4, 'ABC');

  // DELETE /orders/:id
  const res5 = await router.routes[4].handler({ id: 'xyz' }, mockRes, noopNext);
  assert.equal(res5, 'deleted:xyz');
});

test('error forwarding to next for async routes', async () => {
  const router = makeRouter();
  const mockRes = { send: (val) => val };

  // GET /accounts/:id forwards error
  let nextErr1 = null;
  await router.routes[0].handler({ fail: true, id: '123' }, mockRes, (err) => { nextErr1 = err; });
  assert.ok(nextErr1 instanceof Error);
  assert.equal(nextErr1.message, 'account read');

  // POST /accounts forwards error
  let nextErr2 = null;
  await router.routes[1].handler({ fail: true, id: '456' }, mockRes, (err) => { nextErr2 = err; });
  assert.ok(nextErr2 instanceof Error);
  assert.equal(nextErr2.message, 'account create');

  // GET /orders/:id forwards error
  let nextErr3 = null;
  await router.routes[3].handler({ fail: true, id: 'abc' }, mockRes, (err) => { nextErr3 = err; });
  assert.ok(nextErr3 instanceof Error);
  assert.equal(nextErr3.message, 'order read');

  // DELETE /orders/:id forwards error
  let nextErr4 = null;
  await router.routes[4].handler({ fail: true, id: 'xyz' }, mockRes, (err) => { nextErr4 = err; });
  assert.ok(nextErr4 instanceof Error);
  assert.equal(nextErr4.message, 'order delete');
});

test('unrelated helpers and callbacks are preserved unwrapped', async () => {
  assert.equal(documentation, "router.get('/fake', async handler)");
  await assert.rejects(async () => {
    await unrelatedHelper();
  }, { message: 'helper' });

  await assert.rejects(async () => {
    await auditCallback();
  }, { message: 'audit' });
});

