import assert from 'node:assert/strict';
import {describe, it} from 'node:test';
import {makeRouter} from '../src/app.ts';
import {documentation, unrelatedHelper} from '../src/routes/accounts.ts';
import {auditCallback} from '../src/routes/orders.ts';

describe('Router registration and behavior', () => {
  const router = makeRouter();

  it('preserves registration order and methods', () => {
    assert.equal(router.routes.length, 5);
    assert.deepEqual(
      router.routes.map(r => ({ method: r.method, path: r.path })),
      [
        { method: 'GET', path: '/accounts/:id' },
        { method: 'POST', path: '/accounts' },
        { method: 'GET', path: '/health' },
        { method: 'GET', path: '/orders/:id' },
        { method: 'DELETE', path: '/orders/:id' },
      ]
    );
  });

  it('preserves synchronous health route', () => {
    const healthRoute = router.routes[2];
    assert.equal(healthRoute.method, 'GET');
    assert.equal(healthRoute.path, '/health');
    const res = { send: val => val };
    const result = healthRoute.handler({ id: '' }, res, () => {});
    assert.equal(result, 'ok');
    // Ensure it is synchronous and did not return a Promise
    assert.equal(result instanceof Promise, false);
  });

  describe('successful request handling', () => {
    it('handles GET /accounts/:id successfully', async () => {
      const route = router.routes[0];
      const req = { id: 'acc-1' };
      const res = { send: val => val };
      let nextCalled = false;
      const result = await route.handler(req, res, () => { nextCalled = true; });
      assert.equal(result, 'account:acc-1');
      assert.equal(nextCalled, false);
    });

    it('handles POST /accounts (named async function) successfully', async () => {
      const route = router.routes[1];
      const req = { id: 'acc-2' };
      const res = { send: val => val };
      let nextCalled = false;
      const result = await route.handler(req, res, () => { nextCalled = true; });
      assert.equal(result, 'created:acc-2');
      assert.equal(nextCalled, false);
    });

    it('handles GET /orders/:id successfully', async () => {
      const route = router.routes[3];
      const req = { id: 'ord-100' };
      const res = { send: val => val };
      let nextCalled = false;
      const result = await route.handler(req, res, () => { nextCalled = true; });
      assert.equal(result, 'ORD-100');
      assert.equal(nextCalled, false);
    });

    it('handles DELETE /orders/:id successfully', async () => {
      const route = router.routes[4];
      const req = { id: 'ord-200' };
      const res = { send: val => val };
      let nextCalled = false;
      const result = await route.handler(req, res, () => { nextCalled = true; });
      assert.equal(result, 'deleted:ord-200');
      assert.equal(nextCalled, false);
    });
  });

  describe('error forwarding to next', () => {
    it('forwards GET /accounts/:id rejection to next', async () => {
      const route = router.routes[0];
