import assert from 'node:assert/strict';
import {describe, it} from 'node:test';
import {handle} from '../src/app.ts';
import {createContext, forkContext} from '../src/context-factory.ts';
import {describeJob} from '../src/jobs.ts';
import {headers} from '../src/middleware.ts';
import {logFields} from '../src/logging.ts';
import {response} from '../src/response.ts';
import {traceSummary} from '../src/plugins/index.ts';
import {record0, audit0} from '../src/catalog/record0.ts';

describe('RequestContext rename and end-to-end propagation', () => {
  it('creates context with traceId and no requestId member', () => {
    const ctx = createContext('trace-root', 'user-42');
    assert.equal(ctx.traceId, 'trace-root');
    assert.equal(ctx.userId, 'user-42');
    assert.equal('requestId' in ctx, false);
    assert.equal(Object.prototype.hasOwnProperty.call(ctx, 'requestId'), false);
  });

  it('forkContext preserves non-mutation and appends suffix to traceId', () => {
    const parent = createContext('trace-root', 'user-42');
    const child = forkContext(parent, 'worker');

    assert.equal(parent.traceId, 'trace-root');
    assert.equal('requestId' in parent, false);
    assert.equal(child.traceId, 'trace-root/worker');
    assert.equal(child.userId, 'user-42');
    assert.equal('requestId' in child, false);

    const grandchild = forkContext(child, 'step2');
    assert.equal(grandchild.traceId, 'trace-root/worker/step2');
  });

  it('middleware headers output x-request-id with traceId', () => {
    const ctx = createContext('trace-mw', 'user-1');
    const h = headers(ctx);
    assert.deepEqual(h, {'x-request-id': 'trace-mw'});
  });

  it('logging logFields preserves output key requestId mapped from traceId', () => {
    const ctx = createContext('trace-log', 'user-2');
    const fields = logFields(ctx);
    assert.deepEqual(fields, {requestId: 'trace-log', userId: 'user-2'});
  });

  it('response preserves output key requestId mapped from traceId', () => {
    const ctx = createContext('trace-res', 'user-3');
    const res = response(ctx, {done: true});
    assert.deepEqual(res, {requestId: 'trace-res', payload: {done: true}});
  });

  it('propagates trace identifier through full handle pipeline', () => {
    const trace = 'trace-alpha';
    const user = 'user-omega';
    const job = {requestId: 'job-999', name: 'process-queue'};

    const out = handle(trace, user, job);

    assert.equal(out.context.traceId, trace);
    assert.equal(out.context.userId, user);
    assert.equal('requestId' in out.context, false);

    assert.deepEqual(out.headers, {'x-request-id': trace});
    assert.deepEqual(out.logs, {requestId: trace, userId: user});

    assert.equal(out.body.requestId, trace);
    assert.equal(out.body.payload.trace, `${trace}/worker`);
    assert.equal(out.body.payload.name, 'process-queue');
  });
});

describe('Unrelated Job identifier and audit preservation', () => {
  it('keeps Job.requestId separate from RequestContext.traceId', () => {
    const job = {requestId: 'job-distinct-123', name: 'compile'};
    const ctx = createContext('trace-different-456', 'worker-user');

    const result = describeJob(job, ctx);
    assert.equal(result.requestId, 'job-distinct-123');
    assert.equal(result.trace, 'trace-different-456');
    assert.equal(result.audit, 'job:job-distinct-123');
    assert.equal(result.name, 'compile');
  });

  it('preserves Job identifier in handle output body payload', () => {
    const job = {requestId: 'job-unrelated-id', name: 'sync-data'};
    const out = handle('trace-e2e', 'user-e2e', job);

    assert.equal(out.body.payload.requestId, 'job-unrelated-id');
    assert.equal(out.body.payload.audit, 'job:job-unrelated-id');
    assert.notEqual(out.body.payload.requestId, out.body.requestId);
  });
});

describe('Plugins and traceSummary preservation', () => {
  it('traceSummary consumes context and preserves output structure', () => {
    const ctx = createContext('trace-plugin', 'user-plugin');
    const summary = traceSummary(ctx);

    assert.equal(summary.length, 8);
    summary.forEach((item, idx) => {
      assert.deepEqual(item, {
        requestId: 'trace-plugin',
        tag: `plugin${idx}`,
        user: 'user-plugin'
      });
    });
  });
});

describe('Catalog RequestContext independence', () => {
  it('preserves catalog RequestContext types and requestId fields', () => {
    const catalogCtx = {requestId: 'cat-req-10', category: 'hardware'};
    const rec = record0(catalogCtx);

    assert.deepEqual(rec, {
      requestId: 'cat-req-10',
      category: 'hardware',
      label: 'record0:cat-req-10'
    });
    assert.equal(audit0('cat-req-10'), 'audit0:cat-req-10');
  });
});

