import assert from 'node:assert/strict';
import {test} from 'node:test';
import {handle} from '../src/app.ts';
import {createContext, forkContext} from '../src/context-factory.ts';
import {traceSummary} from '../src/plugins/index.ts';
import {describeJob} from '../src/jobs.ts';
import {record0} from '../src/catalog/record0.ts';

test('end-to-end trace propagation and unrelated job identifier', () => {
  const result = handle('trace-123', 'user-456', {requestId: 'job-789', name: 'process-data'});

  // RequestContext has traceId and does NOT have requestId
  assert.equal(result.context.traceId, 'trace-123');
  assert.equal('requestId' in result.context, false);
  assert.equal(result.context.userId, 'user-456');

  // Headers propagate traceId
  assert.deepEqual(result.headers, {'x-request-id': 'trace-123'});

  // Logging output keys preserved (wire key requestId receives traceId)
  assert.deepEqual(result.logs, {requestId: 'trace-123', userId: 'user-456'});

  // Response wire/output keys and forkContext propagation
  assert.equal(result.body.requestId, 'trace-123');
  assert.deepEqual(result.body.payload, {
    requestId: 'job-789',
    trace: 'trace-123/worker',
    audit: 'job:job-789',
    name: 'process-data',
  });
});

test('forkContext preserves non-mutation and suffixes traceId', () => {
  const original = createContext('root-trace', 'user-001');
  const forked = forkContext(original, 'child-step');

  assert.equal(original.traceId, 'root-trace');
  assert.equal('requestId' in original, false);
  assert.equal(forked.traceId, 'root-trace/child-step');
  assert.equal('requestId' in forked, false);
  assert.equal(forked.userId, 'user-001');
});

test('traceSummary and plugin output keys', () => {
  const context = createContext('plugin-trace', 'plugin-user');
  const summary = traceSummary(context);
  assert.equal(summary.length, 8);
  for (let i = 0; i < 8; i++) {
    assert.deepEqual(summary[i], {
      requestId: 'plugin-trace',
      tag: `plugin${i}`,
      user: 'plugin-user',
    });
  }
});

test('describeJob keeps unrelated Job.requestId distinct from context traceId', () => {
  const context = createContext('ctx-trace', 'user-1');
  const job = {requestId: 'job-abc', name: 'sample-job'};
  const description = describeJob(job, context);

  assert.equal(description.requestId, 'job-abc');
  assert.equal(description.trace, 'ctx-trace');
  assert.equal(description.audit, 'job:job-abc');
  assert.equal(description.name, 'sample-job');
});

test('catalog modules retain independent RequestContext and requestId', () => {
  const catalogContext = {requestId: 'cat-999', category: 'hardware'};
  const out = record0(catalogContext);
  assert.deepEqual(out, {
    requestId: 'cat-999',
    category: 'hardware',
    label: 'record0:cat-999',
  });
});

