export function taskLabel(name: string, completed: boolean): string {
  return (completed ? '[x] ' : '[ ] ') + name;
}

import assert from 'node:assert/strict';
import { test } from 'node:test';
import { taskLabel } from '../src/labels.ts';

test('completed task has [x] prefix', () => {
  assert.equal(taskLabel('ship release', true), '[x] ship release');
});

test('incomplete task keeps [ ] prefix', () => {
  assert.equal(taskLabel('write documentation', false), '[ ] write documentation');
});

test('preserves supplied name exactly including whitespace and symbols', () => {
  assert.equal(taskLabel('  spaced task  ', true), '[x]   spaced task  ');
  assert.equal(taskLabel('task with #123 @tag!', false), '[ ] task with #123 @tag!');
  assert.equal(taskLabel('', true), '[x] ');
  assert.equal(taskLabel('', false), '[ ] ');
});

