import assert from 'node:assert/strict';
import {test} from 'node:test';
import {makeRouter} from '../src/app.ts';
import {auditCallback, unrelatedHelper} from '../src/routes/orders.ts';
import {unrelatedHelper as accountHelper, documentation} from '../src/routes/accounts.ts';

function createMockRes() {
  return {
    send(val) {
      return val;
    }
  };
}

test('route registration order and methods', () => {
  const router = makeRouter();
  assert.equal(router.routes.length, 5);

  assert.equal(router.routes[0].method, 'GET');
  assert.equal(router.routes[0].path, '/accounts/:id');

  assert.equal(router.routes[1].method, 'POST');
  assert.equal(router.routes[1].path, '/accounts');

  assert.equal(router.routes[2].method, 'GET');
  assert.equal(router.routes[2].path, '/health');

  assert.equal(router.routes[3].method, 'GET');
  assert.equal(router.routes[3].path, '/orders/:id');

  assert.equal(router.routes[4].method, 'DELETE');
  assert.equal(router.routes[4].path, '/orders/:id');
});

test('successful handling preserves responses', async () => {
  const router = makeRouter();
  const res = createMockRes();
  const nextCalls = [];
  const next = (err) => nextCalls.push(err);

  // GET /accounts/:id
  const getAccountResult = await router.routes[0].handler({ id: 'acc123' }, res, next);
  assert.equal(getAccountResult, 'account:acc123');

  // POST /accounts
  const postAccountResult = await router.routes[1].handler({ id: 'acc456' }, res, next);
  assert.equal(postAccountResult, 'created:acc456');

  // GET /health (synchronous)
  const healthResult = router.routes[2].handler({ id: '0' }, res, next);
  assert.equal(healthResult, 'ok');
  assert.ok(!(healthResult instanceof Promise), 'health route should remain synchronous');

  // GET /orders/:id
  const getOrderResult = await router.routes[3].handler({ id: 'ord789' }, res, next);
  assert.equal(getOrderResult, 'ORD789');

  // DELETE /orders/:id
  const deleteOrderResult = await router.routes[4].handler({ id: 'ord101' }, res, next);
  assert.equal(deleteOrderResult, 'deleted:ord101');

  assert.equal(nextCalls.length, 0);
});

test('error forwarding to next for GET /accounts/:id', async () => {
  const router = makeRouter();
  const res = createMockRes();
  const errors = [];
  const next = (err) => errors.push(err);

  await router.routes[0].handler({ id: 'acc123', fail: true }, res, next);
  assert.equal(errors.length, 1);
  assert.equal(errors[0] instanceof Error, true);
  assert.equal(errors[0].message, 'account read');
});

test('error forwarding to next for POST /accounts (named async function)', async () => {
  const router = makeRouter();
  const res = createMockRes();
  const errors = [];
  const next = (err) => errors.push(err);

  await router.routes[1].handler({ id: 'acc456', fail: true }, res, next);
  assert.equal(errors.length, 1);
  assert.equal(errors[0] instanceof Error, true);
  assert.equal(errors[0].message, 'account create');
});

test('error forwarding to next for GET /orders/:id', async () => {
  const router = makeRouter();
  const res = createMockRes();
  const errors = [];
  const next = (err) => errors.push(err);

  await router.routes[3].handler({ id: 'ord789', fail: true }, res, next);
  assert.equal(errors.length, 1);
  assert.equal(errors[0] instanceof Error, true);
  assert.equal(errors[0].message, 'order read');
});

test('error forwarding to next for DELETE /orders/:id', async () => {
  const router = makeRouter();
  const res = createMockRes();
  const errors = [];
  const next = (err) => errors.push(err);

  await router.routes[4].handler({ id: 'ord101', fail: true }, res, next);
  assert.equal(errors.length, 1);
  assert.equal(errors[0] instanceof Error, true);
  assert.equal(errors[0].message, 'order delete');
});

test('unrelated helpers and callbacks are preserved unwrapped', async () => {
  await assert.rejects(async () => {
    await auditCallback();
  }, { message: 'audit' });

  await assert.rejects(async () => {
    await accountHelper();
  }, { message: 'helper' });

  assert.equal(documentation, "router.get('/fake', async handler)");
});

