import assert from 'node:assert/strict';
import { describe, it } from 'node:test';
import { makeRouter } from '../src/app.ts';
import { auditCallback } from '../src/routes/orders.ts';
import { unrelatedHelper } from '../src/routes/accounts.ts';

describe('Route registration and order', () => {
  it('preserves route registration order and methods', () => {
    const router = makeRouter();
    assert.equal(router.routes.length, 5);
    assert.deepEqual(
      router.routes.map(r => ({ method: r.method, path: r.path })),
      [
        { method: 'GET', path: '/accounts/:id' },
        { method: 'POST', path: '/accounts' },
        { method: 'GET', path: '/health' },
        { method: 'GET', path: '/orders/:id' },
        { method: 'DELETE', path: '/orders/:id' },
      ]
    );
  });

  it('keeps synchronous /health route synchronous', () => {
    const router = makeRouter();
    const healthRoute = router.routes.find(r => r.path === '/health');
    assert.ok(healthRoute);
    const mockRes = { send: (val) => `sent:${val}` };
    const result = healthRoute.handler({ id: '0' }, mockRes, () => {});
    assert.equal(result, 'sent:ok');
    // Ensure it is not an async function returning a promise
    assert.notEqual(Object.prototype.toString.call(result), '[object Promise]');
  });
});

describe('Async route error forwarding and success', () => {
  it('GET /accounts/:id handles success and forwards rejection to next', async () => {
    const router = makeRouter();
    const route = router.routes[0];
    assert.equal(route.path, '/accounts/:id');
    assert.equal(route.method, 'GET');

    // Success case
    const mockRes = { send: (val) => `sent:${val}` };
    let forwardedError = null;
    const next = (err) => { forwardedError = err; };

    const successResult = await route.handler({ id: 'acc-1' }, mockRes, next);
    assert.equal(successResult, 'sent:account:acc-1');
    assert.equal(forwardedError, null);

    // Failure case: error forwarded to next
    forwardedError = null;
    await route.handler({ fail: true, id: 'acc-1' }, mockRes, next);
    assert.ok(forwardedError instanceof Error);
    assert.equal(forwardedError.message, 'account read');
  });

  it('POST /accounts (named async function) handles success and forwards rejection to next', async () => {
    const router = makeRouter();
    const route = router.routes[1];
    assert.equal(route.path, '/accounts');
    assert.equal(route.method, 'POST');

    // Success case
    const mockRes = { send: (val) => `sent:${val}` };
    let forwardedError = null;
    const next = (err) => { forwardedError = err; };

    const successResult = await route.handler({ id: 'acc-new' }, mockRes, next);
    assert.equal(successResult, 'sent:created:acc-new');
    assert.equal(forwardedError, null);

    // Failure case: error forwarded to next
    forwardedError = null;
    await route.handler({ fail: true, id: 'acc-new' }, mockRes, next);
    assert.ok(forwardedError instanceof Error);
    assert.equal(forwardedError.message, 'account create');
  });

  it('GET /orders/:id handles success and forwards rejection to next', async () => {
    const router = makeRouter();
    const route = router.routes[3];
    assert.equal(route.path, '/orders/:id');
    assert.equal(route.method, 'GET');

    // Success case
    const mockRes = { send: (val) => `sent:${val}` };
    let forwardedError = null;
    const next = (err) => { forwardedError = err; };

    const successResult = await route.handler({ id: 'ord-99' }, mockRes, next);
    assert.equal(successResult, 'sent:ORD-99');
    assert.equal(forwardedError, null);

    // Failure case: error forwarded to next
    forwardedError = null;
    await route.handler({ fail: true, id: 'ord-99' }, mockRes, next);
    assert.ok(forwardedError instanceof Error);
    assert.equal(forwardedError.message, 'order read');
  });

  it('DELETE /orders/:id handles success and forwards rejection to next', async () => {
    const router = makeRouter();
    const route = router.routes[4];
    assert.equal(route.path, '/orders/:id');
    assert.equal(route.method, 'DELETE');

    // Success case
    const mockRes = { send: (val) => `sent:${val}` };
    let forwardedError = null;
    const next = (err) => { forwardedError = err; };

    const successResult = await route.handler({ id: 'ord-88' }, mockRes, next);
    assert.equal(successResult, 'sent:deleted:ord-88');
    assert.equal(forwardedError, null);

    // Failure case: error forwarded to next
    forwardedError = null;
    await route.handler({ fail: true, id: 'ord-88' }, mockRes, next);
    assert.ok(forwardedError instanceof Error);
    assert.equal(forwardedError.message, 'order delete');
  });
});

