import assert from 'node:assert/strict';
import {describe, test} from 'node:test';
import {handle} from '../src/app.ts';
import {createContext, forkContext} from '../src/context-factory.ts';
import {describeJob} from '../src/jobs.ts';
import {auditLabel} from '../src/job-types.ts';
import {traceSummary} from '../src/plugins/index.ts';
import {record0} from '../src/catalog/record0.ts';

describe('RequestContext rename and propagation regression tests', () => {
  test('end-to-end propagation and context structure', () => {
    const job = {requestId: 'job-999', name: 'data-sync'};
    const result = handle('trace-abc-123', 'user-xyz-456', job);

    // RequestContext fields
    assert.equal(result.context.traceId, 'trace-abc-123');
    assert.equal(result.context.userId, 'user-xyz-456');
    assert.equal('requestId' in result.context, false, 'RequestContext must not have requestId property');

    // Headers wire key
    assert.equal(result.headers['x-request-id'], 'trace-abc-123');

    // Logging wire keys and output values
    assert.equal(result.logs.requestId, 'trace-abc-123');
    assert.equal(result.logs.userId, 'user-xyz-456');

    // Response wire key
    assert.equal(result.body.requestId, 'trace-abc-123');

    // Worker payload with forkContext suffix
    assert.equal(result.body.payload.trace, 'trace-abc-123/worker');

    // Unrelated Job identifier preserved
    assert.equal(result.body.payload.requestId, 'job-999');
    assert.equal(result.body.payload.audit, 'job:job-999');
    assert.equal(result.body.payload.name, 'data-sync');
  });

  test('forkContext creates a child context without mutating parent', () => {
    const root = createContext('trace-root', 'user-admin');
    const child = forkContext(root, 'subtask');

    assert.equal(root.traceId, 'trace-root');
    assert.equal(root.userId, 'user-admin');
    assert.equal('requestId' in root, false);

    assert.equal(child.traceId, 'trace-root/subtask');
    assert.equal(child.userId, 'user-admin');
    assert.equal('requestId' in child, false);

    // Ensure non-mutation
    assert.notEqual(root, child);
  });

  test('unrelated Job.requestId and audit label preservation', () => {
    const job = {requestId: 'job-independent-id', name: 'batch-task'};
    const ctx = createContext('trace-for-job', 'worker-user');
    const described = describeJob(job, ctx);

    assert.equal(described.requestId, 'job-independent-id');
    assert.equal(described.trace, 'trace-for-job');
    assert.equal(described.audit, 'job:job-independent-id');
    assert.equal(described.name, 'batch-task');

    assert.equal(auditLabel('job-custom'), 'job:job-custom');
  });

  test('traceSummary and plugin propagation', () => {
    const ctx = createContext('plugin-trace-id', 'plugin-user');
    const summary = traceSummary(ctx);

    assert.equal(summary.length, 8);
    for (let i = 0; i < 8; i++) {
      assert.equal(summary[i].requestId, 'plugin-trace-id');
      assert.equal(summary[i].tag, `plugin${i}`);
      assert.equal(summary[i].user, 'plugin-user');
    }
  });

  test('catalog RequestContext types and values remain independent', () => {
    const catCtx = {requestId: 'cat-req-001', category: 'inventory'};
    const catOut = record0(catCtx);

    assert.equal(catOut.requestId, 'cat-req-001');
    assert.equal(catOut.category, 'inventory');
    assert.equal(catOut.label, 'record0:cat-req-001');
  });
});

