import assert from 'node:assert/strict';
import {describe, it} from 'node:test';
import {handle} from '../src/app.ts';
import {createContext, forkContext} from '../src/context-factory.ts';
import {describeJob} from '../src/jobs.ts';
import {traceSummary} from '../src/plugins/index.ts';
import {record0} from '../src/catalog/record0.ts';

describe('RequestContext rename and propagation regression tests', () => {
  it('end-to-end propagation through handle entry point', () => {
    const job = {requestId: 'job-xyz-42', name: 'data-sync'};
    const result = handle('trace-abc-123', 'alice', job);

    // RequestContext on result has traceId and does NOT have requestId compatibility member
    assert.equal(result.context.traceId, 'trace-abc-123');
    assert.equal(result.context.userId, 'alice');
    assert.equal('requestId' in result.context, false, 'RequestContext must not have requestId property');

    // Headers propagated with traceId
    assert.equal(result.headers['x-request-id'], 'trace-abc-123');

    // Logs keep wire/output key named requestId
    assert.equal(result.logs.requestId, 'trace-abc-123');
    assert.equal(result.logs.userId, 'alice');

    // Response wire/output key named requestId preserves trace
    assert.equal(result.body.requestId, 'trace-abc-123');

    // Forked context propagation in worker reaches describeJob
    assert.equal(result.body.payload.trace, 'trace-abc-123/worker');
  });

  it('preserves unrelated Job.requestId and audit label', () => {
    const job = {requestId: 'job-id-999', name: 'background-task'};
    const context = createContext('trace-root', 'bob');

    const jobDescription = describeJob(job, context);

    // Job.requestId is preserved in requestId field
    assert.equal(jobDescription.requestId, 'job-id-999');
    // Trace identifier comes from context.traceId
    assert.equal(jobDescription.trace, 'trace-root');
    // Audit string uses job.requestId
    assert.equal(jobDescription.audit, 'job:job-id-999');
    assert.equal(jobDescription.name, 'background-task');
  });

  it('forkContext non-mutation and suffix behavior', () => {
    const parent = createContext('root-trace', 'charlie');
    const child1 = forkContext(parent, 'stage-1');
    const child2 = forkContext(child1, 'stage-2');

    // Child contexts have suffixed traceId
    assert.equal(child1.traceId, 'root-trace/stage-1');
    assert.equal(child2.traceId, 'root-trace/stage-1/stage-2');
    assert.equal(child1.userId, 'charlie');
    assert.equal(child2.userId, 'charlie');

    // Neither child has requestId
    assert.equal('requestId' in child1, false);
    assert.equal('requestId' in child2, false);

    // Non-mutation: parent is untouched
    assert.equal(parent.traceId, 'root-trace');
    assert.equal(child1.traceId, 'root-trace/stage-1');
  });

  it('traceSummary preserves plugin consumers and output keys', () => {
    const context = createContext('trace-summary-id', 'dan');
    const summaries = traceSummary(context);

    assert.equal(summaries.length, 8);
    summaries.forEach((summary, index) => {
      assert.equal(summary.requestId, 'trace-summary-id');
      assert.equal(summary.tag, `plugin${index}`);
      assert.equal(summary.user, 'dan');
    });
  });

  it('catalog RequestContext APIs and requestId fields remain independent and intact', () => {
    const catalogContext = {requestId: 'cat-item-1', category: 'inventory'};
    const record = record0(catalogContext);

    assert.equal(record.requestId, 'cat-item-1');
    assert.equal(record.category, 'inventory');
    assert.equal(record.label, 'record0:cat-item-1');
  });
});

